arguments.content:
#!/bin/bash
# usage: t.sh NAME configure-args...
name=$1; shift
rm -rf /tmp/w/$name; mkdir -p /tmp/w/$name
cp -r /app /tmp/w/$name/src
cd /tmp/w/$name/src && autoreconf -fi >/tmp/w/$name/ar.log 2>&1 || { echo autoreconf fail; tail -20 /tmp/w/$name/ar.log; exit 1; }
mkdir ../b && cd ../b
../src/configure --prefix=/tmp/w/$name/inst "$@" >../conf.log 2>&1 || { echo configure fail; tail ../conf.log; exit 1; }
make >../make.log 2>&1 || { echo make fail; tail -30 ../make.log; exit 1; }
make check >../check.log 2>&1 || { echo check fail; tail -40 ../check.log; exit 1; }
grep -E '^# (TOTAL|PASS|FAIL)' tests/test-suite.log tests/*.log 2>/dev/null | head -3
make install DESTDIR=/tmp/w/$name/dd >../inst.log 2>&1 || { echo install fail; tail ../inst.log; exit 1; }
(cd /tmp/w/$name/dd && find . \( -type f -o -type l \) -printf '%p -> %l\n')
grep -r "/tmp/w/$name/dd" /tmp/w/$name/dd && echo DESTDIR LEAK
make uninstall DESTDIR=/tmp/w/$name/dd >../un.log 2>&1 || { echo uninstall fail; tail ../un.log; exit 1; }
echo "left after uninstall:"; find /tmp/w/$name/dd \( -type f -o -type l \)

